import { Command } from 'commander';

// Kept in sync with the commands registered in cli.ts, env.ts, and
// inspect.ts. The completion scripts below are hand-written (not derived
// from the live Commander program) so a command, alias, or option added
// there must be mirrored here — see tests/completion.test.ts for a
// regression check that flags top-level commands missing from either
// script.
const BASH_COMPLETION_SCRIPT = `#!/usr/bin/env bash
# ILN CLI bash completion script
# Generated by @invoice-liquidity/cli

_iln_completions() {
  local cur prev top sub
  COMPREPLY=()
  cur="\${COMP_WORDS[COMP_CWORD]}"
  prev="\${COMP_WORDS[COMP_CWORD-1]}"
  top="\${COMP_WORDS[1]}"
  sub="\${COMP_WORDS[2]}"
  local commands="submit fund pay status list history watch export stats reputation network compat protocol-config config xdr dashboard generate dev update changelog wallet interactive tutorial man alias env inspect completion"

  if [[ \${COMP_CWORD} -eq 1 ]]; then
    COMPREPLY=( $(compgen -W "\${commands}" -- "\${cur}") )
    return 0
  fi

  case "\${top}" in
    submit)
      COMPREPLY=( $(compgen -W "--payer --amount --due --rate --token --yes --help" -- "\${cur}") )
      return 0
      ;;
    fund)
      COMPREPLY=( $(compgen -W "--id --amount --yes --help" -- "\${cur}") )
      return 0
      ;;
    pay)
      COMPREPLY=( $(compgen -W "--id --yes --help" -- "\${cur}") )
      return 0
      ;;
    status)
      COMPREPLY=( $(compgen -W "--id --yes --help" -- "\${cur}") )
      return 0
      ;;
    list)
      COMPREPLY=( $(compgen -W "--address --yes --help" -- "\${cur}") )
      return 0
      ;;
    history)
      COMPREPLY=( $(compgen -W "--address --id --action --limit --format --yes --help" -- "\${cur}") )
      return 0
      ;;
    watch)
      COMPREPLY=( $(compgen -W "--id --interval --help" -- "\${cur}") )
      return 0
      ;;
    export)
      COMPREPLY=( $(compgen -W "--address --output --help" -- "\${cur}") )
      return 0
      ;;
    stats)
      COMPREPLY=( $(compgen -W "--api-url --help" -- "\${cur}") )
      return 0
      ;;
    reputation)
      if [[ \${COMP_CWORD} -eq 2 ]]; then
        COMPREPLY=( $(compgen -W "get --help" -- "\${cur}") )
      else
        COMPREPLY=( $(compgen -W "--help" -- "\${cur}") )
      fi
      return 0
      ;;
    network)
      if [[ \${COMP_CWORD} -eq 2 ]]; then
        COMPREPLY=( $(compgen -W "switch --help" -- "\${cur}") )
      elif [[ "\${sub}" == "switch" && \${COMP_CWORD} -eq 3 ]]; then
        COMPREPLY=( $(compgen -W "testnet mainnet standalone" -- "\${cur}") )
      else
        COMPREPLY=( $(compgen -W "--help" -- "\${cur}") )
      fi
      return 0
      ;;
    compat)
      if [[ \${COMP_CWORD} -eq 2 ]]; then
        COMPREPLY=( $(compgen -W "check --help" -- "\${cur}") )
      else
        COMPREPLY=( $(compgen -W "--help" -- "\${cur}") )
      fi
      return 0
      ;;
    protocol-config)
      COMPREPLY=( $(compgen -W "--help" -- "\${cur}") )
      return 0
      ;;
    config)
      if [[ \${COMP_CWORD} -eq 2 ]]; then
        COMPREPLY=( $(compgen -W "init show --help" -- "\${cur}") )
      elif [[ "\${sub}" == "init" ]]; then
        COMPREPLY=( $(compgen -W "--cwd --help" -- "\${cur}") )
      else
        COMPREPLY=( $(compgen -W "--help" -- "\${cur}") )
      fi
      return 0
      ;;
    xdr)
      if [[ \${COMP_CWORD} -eq 2 ]]; then
        COMPREPLY=( $(compgen -W "decode --help" -- "\${cur}") )
      else
        COMPREPLY=( $(compgen -W "--help" -- "\${cur}") )
      fi
      return 0
      ;;
    dashboard)
      COMPREPLY=( $(compgen -W "--refresh --export --help" -- "\${cur}") )
      return 0
      ;;
    generate)
      COMPREPLY=( $(compgen -W "--list --preview --out --var --help" -- "\${cur}") )
      return 0
      ;;
    dev)
      if [[ \${COMP_CWORD} -eq 2 ]]; then
        COMPREPLY=( $(compgen -W "start stop reset status seed --help" -- "\${cur}") )
      elif [[ "\${sub}" == "seed" ]]; then
        COMPREPLY=( $(compgen -W "--scenario --count --token --help" -- "\${cur}") )
      elif [[ "\${sub}" == "status" ]]; then
        COMPREPLY=( $(compgen -W "--json --help" -- "\${cur}") )
      else
        COMPREPLY=( $(compgen -W "--help" -- "\${cur}") )
      fi
      return 0
      ;;
    update|changelog|interactive|tutorial)
      COMPREPLY=( $(compgen -W "--help" -- "\${cur}") )
      return 0
      ;;
    wallet)
      if [[ \${COMP_CWORD} -eq 2 ]]; then
        COMPREPLY=( $(compgen -W "create import list fund delete --help" -- "\${cur}") )
      elif [[ "\${sub}" == "create" ]]; then
        COMPREPLY=( $(compgen -W "--name --password --help" -- "\${cur}") )
      elif [[ "\${sub}" == "import" ]]; then
        COMPREPLY=( $(compgen -W "--name --secret --password --help" -- "\${cur}") )
      elif [[ "\${sub}" == "list" ]]; then
        COMPREPLY=( $(compgen -W "--json --help" -- "\${cur}") )
      elif [[ "\${sub}" == "fund" ]]; then
        COMPREPLY=( $(compgen -W "--name --password --friendbot --help" -- "\${cur}") )
      elif [[ "\${sub}" == "delete" ]]; then
        COMPREPLY=( $(compgen -W "--name --help" -- "\${cur}") )
      else
        COMPREPLY=( $(compgen -W "--help" -- "\${cur}") )
      fi
      return 0
      ;;
    man)
      COMPREPLY=( $(compgen -W "submit fund pay status list history watch export stats dashboard dev --help" -- "\${cur}") )
      return 0
      ;;
    alias)
      if [[ \${COMP_CWORD} -eq 2 ]]; then
        COMPREPLY=( $(compgen -W "list add remove rm --help" -- "\${cur}") )
      elif [[ "\${sub}" == "list" ]]; then
        COMPREPLY=( $(compgen -W "--json --help" -- "\${cur}") )
      else
        COMPREPLY=( $(compgen -W "--help" -- "\${cur}") )
      fi
      return 0
      ;;
    env)
      if [[ \${COMP_CWORD} -eq 2 ]]; then
        COMPREPLY=( $(compgen -W "list use create delete show --help" -- "\${cur}") )
      elif [[ "\${sub}" == "list" || "\${sub}" == "show" ]]; then
        COMPREPLY=( $(compgen -W "--json --help" -- "\${cur}") )
      elif [[ "\${sub}" == "create" ]]; then
        COMPREPLY=( $(compgen -W "--contract-id --rpc-url --network-passphrase --keypair-path --help" -- "\${cur}") )
      else
        COMPREPLY=( $(compgen -W "--help" -- "\${cur}") )
      fi
      return 0
      ;;
    inspect)
      if [[ \${COMP_CWORD} -eq 2 ]]; then
        COMPREPLY=( $(compgen -W "invoice --help" -- "\${cur}") )
      elif [[ "\${sub}" == "invoice" ]]; then
        COMPREPLY=( $(compgen -W "--format --help" -- "\${cur}") )
      else
        COMPREPLY=( $(compgen -W "--help" -- "\${cur}") )
      fi
      return 0
      ;;
    completion)
      COMPREPLY=( $(compgen -W "bash zsh --help" -- "\${cur}") )
      return 0
      ;;
  esac

  if [[ "\${cur}" == -* ]]; then
    COMPREPLY=( $(compgen -W "--json --quiet --help" -- "\${cur}") )
    return 0
  fi

  COMPREPLY=( $(compgen -W "\${commands}" -- "\${cur}") )
  return 0
}

complete -F _iln_completions iln
`;

const ZSH_COMPLETION_SCRIPT = `#compdef iln
# ILN CLI zsh completion script
# Generated by @invoice-liquidity/cli

_iln() {
  local -a commands
  commands=(
    'submit:Submit a new invoice'
    'fund:Fund an invoice'
    'pay:Mark an invoice as paid'
    'status:Show invoice status'
    'list:List invoices by address'
    'history:Show invoice history'
    'watch:Watch an invoice for real-time status updates'
    'export:Export invoices to CSV'
    'stats:Show protocol-wide analytics'
    'reputation:Query on-chain reputation scores'
    'network:Manage the active Stellar network'
    'compat:SDK and contract compatibility utilities'
    'protocol-config:Show live protocol configuration'
    'config:Manage the local ILN config file'
    'xdr:Inspect Soroban XDR values'
    'dashboard:Launch real-time dashboard'
    'generate:Generate boilerplate code from a template'
    'dev:Development utilities'
    'update:Check for and install CLI updates'
    'changelog:Show the changelog for a version'
    'wallet:Manage Stellar keypairs for use with ILN'
    'interactive:Start an interactive guided session'
    'tutorial:Step-by-step guided tutorial'
    'man:Print a man page for iln or a subcommand'
    'alias:Manage CLI command aliases'
    'env:Manage ILN environments'
    'inspect:Inspect contract state'
    'completion:Generate shell completion scripts'
  )

  local -a dev_subcommands
  dev_subcommands=(
    'start:Start local development environment'
    'stop:Stop local development environment'
    'reset:Reset local development environment'
    'status:Show local environment status'
    'seed:Create and fund testnet accounts'
  )

  local -a compat_subcommands
  compat_subcommands=(
    'check:Check SDK compatibility'
  )

  local -a xdr_subcommands
  xdr_subcommands=(
    'decode:Decode base64 Soroban ScVal XDR'
  )

  local -a reputation_subcommands
  reputation_subcommands=(
    'get:Get the reputation score of an address'
  )

  local -a network_subcommands
  network_subcommands=(
    'switch:Switch the active network'
  )

  local -a config_subcommands
  config_subcommands=(
    'init:Generate a starter .ilnrc.json config file'
    'show:Show the resolved configuration'
  )

  local -a wallet_subcommands
  wallet_subcommands=(
    'create:Generate a new Stellar keypair'
    'import:Import an existing Stellar secret key'
    'list:List all stored wallets'
    'fund:Fund a wallet from Stellar Friendbot'
    'delete:Delete a stored wallet'
  )

  local -a alias_subcommands
  alias_subcommands=(
    'list:List all configured aliases'
    'add:Add a new custom alias'
    'remove:Remove a custom alias'
  )

  local -a env_subcommands
  env_subcommands=(
    'list:List all configured environments'
    'use:Switch to a different environment'
    'create:Create a new environment'
    'delete:Delete an environment'
    'show:Show details of a specific environment'
  )

  local -a inspect_subcommands
  inspect_subcommands=(
    'invoice:Print full invoice struct as formatted JSON'
  )

  _arguments -C \
    '--json[Reserved for future machine-readable output]' \
    '--quiet[Suppress informational messages]' \
    '--help[Show help]' \
    '1:command:->command' \
    '*::arg:->args'

  case $state in
    command)
      _describe 'command' commands
      ;;
    args)
      case $words[1] in
        submit)
          _arguments \
            '--payer[Stellar address of the payer]:payer: ' \
            '--amount[Invoice amount in display units]:amount: ' \
            '--due[Due date as YYYY-MM-DD or Unix timestamp]:due: ' \
            '--rate[Discount rate in basis points]:rate: ' \
            '--token[Override token contract ID]:token: ' \
            '--yes[Skip interactive prompts]' \
            '--help[Show help]'
          ;;
        fund)
          _arguments \
            '--id[Invoice ID]:id: ' \
            '--amount[Amount to fund in display units]:amount: ' \
            '--yes[Skip interactive prompts]' \
            '--help[Show help]'
          ;;
        pay)
          _arguments \
            '--id[Invoice ID]:id: ' \
            '--yes[Skip interactive prompts]' \
            '--help[Show help]'
          ;;
        status)
          _arguments \
            '--id[Invoice ID]:id: ' \
            '--yes[Skip interactive prompts]' \
            '--help[Show help]'
          ;;
        list)
          _arguments \
            '--address[Stellar address to query]:address: ' \
            '--yes[Skip interactive prompts]' \
            '--help[Show help]'
          ;;
        history)
          _arguments \
            '--address[Stellar address to query]:address: ' \
            '--id[Filter to specific invoice ID]:id: ' \
            '--action[Filter by action type]:action:(submit fund pay)' \
            '--limit[Maximum number of results]:limit: ' \
            '--format[Output format]:format:(table json)' \
            '--yes[Skip interactive prompts]' \
            '--help[Show help]'
          ;;
        watch)
          _arguments \
            '--id[Invoice ID]:id: ' \
            '--interval[Poll interval in milliseconds]:interval: ' \
            '--help[Show help]'
          ;;
        export)
          _arguments \
            '--address[Filter by freelancer, payer, or funder address]:address: ' \
            '--output[Output file path, or - for stdout]:output: ' \
            '--help[Show help]'
          ;;
        stats)
          _arguments \
            '--api-url[Override the analytics API base URL]:url: ' \
            '--help[Show help]'
          ;;
        reputation)
          _arguments -C \
            '1:subcommand:->subcommand' \
            '*::arg:->args'

          case $state in
            subcommand)
              _describe 'subcommand' reputation_subcommands
              ;;
            args)
              _arguments \
                '[address]:address: ' \
                '--help[Show help]'
              ;;
          esac
          ;;
        network)
          _arguments -C \
            '1:subcommand:->subcommand' \
            '*::arg:->args'

          case $state in
            subcommand)
              _describe 'subcommand' network_subcommands
              ;;
            args)
              case $words[1] in
                switch)
                  _arguments '1:target:(testnet mainnet standalone)'
                  ;;
                *)
                  _arguments '--help[Show help]'
                  ;;
              esac
              ;;
          esac
          ;;
        config)
          _arguments -C \
            '1:subcommand:->subcommand' \
            '*::arg:->args'

          case $state in
            subcommand)
              _describe 'subcommand' config_subcommands
              ;;
            args)
              case $words[1] in
                init)
                  _arguments '--cwd[Directory to write the config file into]:dir: '
                  ;;
                *)
                  _arguments '--help[Show help]'
                  ;;
              esac
              ;;
          esac
          ;;
        dev)
          _arguments -C \
            '1:subcommand:->subcommand' \
            '*::arg:->args'

          case $state in
            subcommand)
              _describe 'subcommand' dev_subcommands
              ;;
            args)
              case $words[1] in
                seed)
                  _arguments \
                    '--scenario[Seeding scenario]:scenario:(new-user active-lp disputed)' \
                    '--count[Number of records to seed]:count: ' \
                    '--token[Specific token to use]:token:(USDC EURC)' \
                    '--help[Show help]'
                  ;;
                status)
                  _arguments '--json[Output machine-readable JSON]'
                  ;;
                *)
                  _arguments '--help[Show help]'
                  ;;
              esac
          esac
          ;;
        compat)
          _arguments -C \
            '1:subcommand:->subcommand' \
            '*::arg:->args'

          case $state in
            subcommand)
              _describe 'subcommand' compat_subcommands
              ;;
            args)
              _arguments '--help[Show help]'
              ;;
          esac
          ;;
        xdr)
          _arguments -C \
            '1:subcommand:->subcommand' \
            '*::arg:->args'

          case $state in
            subcommand)
              _describe 'subcommand' xdr_subcommands
              ;;
            args)
              _arguments \
                '[base64]:base64: ' \
                '--help[Show help]'
              ;;
          esac
          ;;
        dashboard)
          _arguments \
            '--refresh[Refresh interval in milliseconds]:refresh: ' \
            '--export[Export dashboard data to JSON file]:file: ' \
            '--help[Show help]'
          ;;
        generate)
          _arguments \
            '[template]:template: ' \
            '--list[List available templates and exit]' \
            '--preview[Print generated output without writing to disk]' \
            '--out[Output directory]:dir: ' \
            '*--var[Set a template variable]:key=value: ' \
            '--help[Show help]'
          ;;
        update)
          _arguments \
            '[version]:version: ' \
            '--help[Show help]'
          ;;
        changelog)
          _arguments \
            '[version]:version: ' \
            '--help[Show help]'
          ;;
        wallet)
          _arguments -C \
            '1:subcommand:->subcommand' \
            '*::arg:->args'

          case $state in
            subcommand)
              _describe 'subcommand' wallet_subcommands
              ;;
            args)
              case $words[1] in
                create)
                  _arguments \
                    '--name[Wallet name identifier]:name: ' \
                    '--password[Encryption password for the wallet]:password: '
                  ;;
                import)
                  _arguments \
                    '--name[Wallet name identifier]:name: ' \
                    '--secret[Stellar secret key]:secret: ' \
                    '--password[Encryption password for the wallet]:password: '
                  ;;
                list)
                  _arguments '--json[Output machine-readable JSON]'
                  ;;
                fund)
                  _arguments \
                    '--name[Wallet name to fund]:name: ' \
                    '--password[Encryption password for the wallet]:password: ' \
                    '--friendbot[Friendbot URL]:url: '
                  ;;
                delete)
                  _arguments '--name[Wallet name to delete]:name: '
                  ;;
                *)
                  _arguments '--help[Show help]'
                  ;;
              esac
              ;;
          esac
          ;;
        interactive)
          _arguments '--help[Show help]'
          ;;
        tutorial)
          _arguments '--help[Show help]'
          ;;
        man)
          _arguments \
            '[command]:command:(submit fund pay status list history watch export stats dashboard dev)' \
            '--help[Show help]'
          ;;
        alias)
          _arguments -C \
            '1:subcommand:->subcommand' \
            '*::arg:->args'

          case $state in
            subcommand)
              _describe 'subcommand' alias_subcommands
              ;;
            args)
              case $words[1] in
                list)
                  _arguments '--json[Output machine-readable JSON]'
                  ;;
                *)
                  _arguments '--help[Show help]'
                  ;;
              esac
              ;;
          esac
          ;;
        env)
          _arguments -C \
            '1:subcommand:->subcommand' \
            '*::arg:->args'

          case $state in
            subcommand)
              _describe 'subcommand' env_subcommands
              ;;
            args)
              case $words[1] in
                list|show)
                  _arguments '--json[Output machine-readable JSON]'
                  ;;
                create)
                  _arguments \
                    '--contract-id[Stellar contract ID]:id: ' \
                    '--rpc-url[RPC server URL]:url: ' \
                    '--network-passphrase[Stellar network passphrase]:phrase: ' \
                    '--keypair-path[Path to keypair file]:path: '
                  ;;
                *)
                  _arguments '--help[Show help]'
                  ;;
              esac
              ;;
          esac
          ;;
        inspect)
          _arguments -C \
            '1:subcommand:->subcommand' \
            '*::arg:->args'

          case $state in
            subcommand)
              _describe 'subcommand' inspect_subcommands
              ;;
            args)
              _arguments \
                '--format[Output format]:format: ' \
                '--help[Show help]'
              ;;
          esac
          ;;
        completion)
          _arguments '1:shell:(bash zsh)'
          ;;
      esac
      ;;
  esac
}

_iln "$@"
`;

export function generateBashCompletion(): string {
  return BASH_COMPLETION_SCRIPT;
}

export function generateZshCompletion(): string {
  return ZSH_COMPLETION_SCRIPT;
}

export function registerCompletionCommand(program: Command): void {
  program
    .command('completion')
    .description('Generate shell completion scripts')
    .argument('[shell]', 'shell type: bash or zsh', 'bash')
    .action((shell: string) => {
      switch (shell) {
        case 'bash':
          process.stdout.write(generateBashCompletion());
          break;
        case 'zsh':
          process.stdout.write(generateZshCompletion());
          break;
        default:
          throw new Error(`Unsupported shell: ${shell}. Supported shells: bash, zsh`);
      }
    });
}
